import { app, BrowserWindow, dialog, ipcMain, Menu, OpenDialogReturnValue, SaveDialogReturnValue } from 'electron';
import fs from 'fs/promises';
import express, { Request, Response } from 'express';
import * as puppeteer from 'puppeteer';
import log from 'electron-log';
import path from 'path';

// Типы для данных
interface CSVParseRequest {
  data: string;
}

interface WebParseRequest {
  url: string;
}

interface SaveResultRequest {
  data: any;
  format: string;
  filePath?: string; 
}

// Настройка логирования
log.initialize({ preload: true });
log.transports.file.level = 'debug';
log.transports.file.fileName = 'main.log';
log.transports.file.maxSize = 5 * 1024 * 1024; // 5MB
log.transports.console.level = 'debug';

log.info('======== Starting Application ========');
log.info(`Platform: ${process.platform}`);
log.info(`Node version: ${process.versions.node}`);
log.info(`Chrome version: ${process.versions.chrome}`);
log.info(`Electron version: ${process.versions.electron}`);
log.info(`App version: ${app.getVersion()}`);
log.info(`User data path: ${app.getPath('userData')}`);

// 1. Инициализация Express-сервера
const initServer = (): express.Application => {
  const server = express();
  server.use(express.json());
  
  // API для парсинга CSV
  server.post('/parse/csv', async (req: Request<{}, {}, CSVParseRequest>, res: Response) => {
    try {
      const parsed = req.body.data.split('\n').map((line: string) => line.split(','));
      res.json(parsed);
      log.info('CSV parsed successfully');
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      log.error('CSV parsing error:', error);
      res.status(500).json({ error: message });
    }
  });

  // API для парсинга веб-страниц
  server.post('/parse/web', async (req: Request<{}, {}, WebParseRequest>, res: Response) => {
    let browser: puppeteer.Browser | null = null;
    try {
      log.info(`Starting web parsing for URL: ${req.body.url}`);
      browser = await puppeteer.launch({
        args: ['--no-sandbox', '--disable-setuid-sandbox'],
        dumpio: true
      });
      
      const page = await browser.newPage();
      await page.goto(req.body.url, { waitUntil: 'networkidle2' });
      log.debug(`Page loaded: ${req.body.url}`);
      
      const data = await page.evaluate(() => ({
        title: document.title,
        headers: Array.from(document.querySelectorAll('h1, h2, h3'))
          .map(el => el.textContent?.trim() || '')
      }));
      
      res.json(data);
      log.info(`Web parsing completed for: ${req.body.url}`);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      log.error('Web parsing failed:', error);
      res.status(500).json({ error: message });
    } finally {
      if (browser) {
        log.debug('Closing browser instance');
        await browser.close();
      }
    }
  });

  const PORT = 3000;
  server.listen(PORT, () => {
    log.info(`API server started on port ${PORT}`);
  });
  
  return server;
};

// 2. Конфигурация Electron
let mainWindow: BrowserWindow | null = null;

const createWindow = async (): Promise<void> => {
  try {
    log.info('Creating main browser window');
    const preloadPath = path.join(__dirname, 'preload.js');
    log.debug(`Preload path: ${preloadPath}`);
    
    const window = new BrowserWindow({
      width: 1200,
      height: 800,
      webPreferences: {
        nodeIntegration: false,
        contextIsolation: true,
        preload: preloadPath,
        sandbox: true
      },
      show: false
    });
    
    mainWindow = window;
    
    window.once('ready-to-show', () => {
      window.show();
      log.debug('Main window is ready and shown');
    });
    
    window.on('closed', () => {
      log.info('Main window closed');
      mainWindow = null;
    });
    
    // Загрузка React-приложения
    if (process.env.NODE_ENV === 'development') {
      const devUrl = 'http://localhost:5173';
      log.info(`Loading development URL: ${devUrl}`);
      await window.loadURL(devUrl);
      window.webContents.openDevTools();
    } else {
      const indexPath = path.join(app.getAppPath(), 'dist', 'renderer', 'index.html');
      log.info(`Loading production file: ${indexPath}`);
      await window.loadFile(indexPath);
    }
    
    // Создание кастомного меню
    const menuTemplate: Electron.MenuItemConstructorOptions[] = [
      {
        label: 'Файл',
        submenu: [
          {
            label: 'Импорт CSV',
            click: () => {
              if (window && !window.isDestroyed()) {
                log.info('Menu action: import-csv');
                window.webContents.send('import-csv');
              } else {
                log.warn('Main window not available for sending message');
              }
            }
          },
          { type: 'separator' },
          { role: 'quit' }
        ]
      },
      {
        label: 'Парсинг',
        submenu: [
          {
            label: 'С сайта',
            click: () => {
              if (window && !window.isDestroyed()) {
                log.info('Menu action: parse-web');
                window.webContents.send('parse-web');
              } else {
                log.warn('Main window not available for sending message');
              }
            }
          }
        ]
      }
    ];
    
    const menu = Menu.buildFromTemplate(menuTemplate);
    Menu.setApplicationMenu(menu);
    log.debug('Application menu set');
    
  } catch (error) {
    log.error('Window creation failed:', error);
    app.quit();
  }
};

// 3. IPC обработчики
const setupIPC = (): void => {
  // Чтение файлов
  ipcMain.handle('read-file', async (_event, filePath: string) => {
    try {
      log.debug(`Reading file: ${filePath}`);
      const content = await fs.readFile(filePath, 'utf-8');
      log.debug(`File read successfully: ${filePath}`);
      return content;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'File read error';
      log.error(`Error reading file ${filePath}:`, err);
      throw new Error(`Ошибка чтения файла: ${message}`);
    }
  });
  
  // Сохранение результатов
  ipcMain.handle('save-result', async (_event, { data, format = 'json', filePath }: SaveResultRequest) => {
    try {
      let targetPath = filePath;
      
      // Если путь не указан - используем документы по умолчанию
      if (!targetPath) {
        const outputDir = app.getPath('documents');
        targetPath = path.join(outputDir, `parsed_${Date.now()}.${format}`);
      }
      
      log.info(`Saving result to: ${targetPath}`);
      
      const content = format === 'json'
        ? JSON.stringify(data, null, 2)
        : data.map((row: any[]) => row.join(',')).join('\n');
      
      await fs.writeFile(targetPath, content);
      log.debug(`File saved successfully: ${targetPath}`);
      return targetPath;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'File save error';
      log.error('Error saving file:', err);
      throw new Error(`Ошибка сохранения файла: ${message}`);
    }
  });
  
  // Диалоги файловой системы
  ipcMain.handle('dialog:openFile', async (): Promise<string | null> => {
    const filePaths = dialog.showOpenDialogSync({ properties: ['openFile'] });
    if (!filePaths || filePaths.length === 0) return null;
    return filePaths[0];
  });

  ipcMain.handle('dialog:openDirectory', async (): Promise<string | null> => {
    const filePaths = dialog.showOpenDialogSync({ properties: ['openDirectory'] });
    if (!filePaths || filePaths.length === 0) return null;
    return filePaths[0];
  });

  ipcMain.handle('dialog:saveFile', async (): Promise<string | null> => {
    const filePath = dialog.showSaveDialogSync({
      properties: ['createDirectory'],
      filters: [{ name: 'JSON Files', extensions: ['json'] }],
    });
    if (!filePath) return null;
    return filePath;
  });


    
    // Обработка сообщений от рендерера
    ipcMain.on('show-message', (_event, message: string) => {
      log.info(`Message from renderer: ${message}`);
    });
  };

// 4. Главная функция
app.whenReady().then(async () => {
  log.info('App is ready');
  
  try {
    initServer();
    await createWindow();
    setupIPC();
  } catch (error) {
    log.fatal('Application initialization failed:', error);
    app.quit();
  }
  
  app.on('activate', () => {
    log.debug('App activate event');
    if (BrowserWindow.getAllWindows().length === 0) {
      log.info('Recreating main window');
      createWindow();
    }
  });
});

app.on('window-all-closed', () => {
  log.info('All windows closed');
  if (process.platform !== 'darwin') {
    log.info('Quitting application');
    app.quit();
  }
});

// 5. Глобальная обработка ошибок
process.on('uncaughtException', (error) => {
  log.fatal('Uncaught Exception:', error);
  app.quit();
});

process.on('unhandledRejection', (reason) => {
  log.fatal('Unhandled Rejection:', reason);
  app.quit();
});

// Расширение типов для логгера
declare module 'electron-log' {
  interface LogFunctions {
    fatal(...params: any[]): void;
  }
}